// Generated by tools/build_prototype.py from domain.mjs and app.mjs
(()=>{
const categories = ['Plumbing','Electrical','Heating & ventilation','Appliance repair','Furniture & carpentry','Finishing work'];
const profiles = [
  {id:'p1',name:'Ayan M.',initials:'AM',trade:'Plumbing specialist',rating:4.9,count:28,experience:'6 years of experience, self-declared',bio:'Kitchen and bathroom plumbing, leak diagnosis and fixture installation.',works:['Kitchen sink installation','Bathroom fixture replacement'],reviews:['Explained the scope before starting.','Arrived within the agreed time window.']},
  {id:'p2',name:'Dana S.',initials:'DS',trade:'Home repair specialist',rating:4.8,count:41,experience:'8 years of experience, self-declared',bio:'Residential repairs with clear estimates and materials discussed in advance.',works:['Bathroom pipe repair','Utility room renovation'],reviews:['Clear estimate and careful work.','The final result matched our agreement.']},
  {id:'p3',name:'Timur K.',initials:'TK',trade:'Independent technician',rating:0,count:0,experience:'3 years of experience, self-declared',bio:'Small repairs and installations. Building a new profile on UyCare.',works:['Mixer replacement','Drain maintenance'],reviews:[]}
];
function seed(){return {version:1,role:'customer',selected:'r1',requests:[{id:'r1',title:'Fix a leaking kitchen sink',description:'Water leaks under the kitchen sink. Please inspect the connection and replace the seal if needed.',category:'Plumbing',property:'Apartment',area:'Almaty, Bostandyk district',date:'2026-10-25',budget:18000,status:'Open',offers:[{id:'o1',providerId:'p1',price:15000,time:'25 October, 10:00–12:00',scope:'Inspection and labour included. Replacement parts agreed separately.'},{id:'o2',providerId:'p2',price:18000,time:'25 October, 14:00–16:00',scope:'Inspection, labour and a standard seal included. Other parts quoted first.'},{id:'o3',providerId:'p3',price:12000,time:'26 October, 09:00–11:00',scope:'Labour and travel included. Materials are separate.'}],messages:[],events:['Request published'],review:null,accepted:null,cancelBy:null}]};}
function suggestCategory(text){
 const s=text.toLowerCase();
 const rules=[['Plumbing',/sink|pipe|leak|tap|труб|кран|раков|құбыр|су ағып/],['Electrical',/socket|wire|electric|light|розет|электр|жарық/],['Heating & ventilation',/heat|radiator|ventilat|отоп|радиатор|жылыту/],['Appliance repair',/washer|fridge|appliance|холодиль|стираль|тоңазыт/],['Furniture & carpentry',/furniture|cabinet|wood|мебел|шкаф|жиһаз/],['Finishing work',/paint|wallpaper|tile|краск|обои|плитк|бояу/]];
 const hits=rules.filter(([,re])=>re.test(s));return hits.length===1?hits[0][0]:null;
}
function createRequest(s,input){
 if(!input.title?.trim()||!input.description?.trim()||!input.area?.trim()||!input.date||!categories.includes(input.category))throw Error('Complete the title, description, category, area and date.');
 if(input.budget!==''&&(!Number.isFinite(Number(input.budget))||Number(input.budget)<=0))throw Error('Enter a positive budget or leave it blank.');
 const today=new Date();today.setHours(0,0,0,0);const day=new Date(input.date+'T00:00:00');
 if(Number.isNaN(day.getTime())||day<today)throw Error('Choose today or a future date.');
 const r={...input,title:input.title.trim(),description:input.description.trim(),budget:input.budget===''?null:Number(input.budget),id:'r'+Date.now(),status:'Open',offers:[],messages:[],events:['Request published'],accepted:null,review:null,cancelBy:null};s.requests.unshift(r);s.selected=r.id;return r;
}
function submitOffer(r,offer){if(r.status!=='Open')throw Error('This request is no longer accepting offers.');if(!Number.isFinite(Number(offer.price))||Number(offer.price)<=0||!offer.time?.trim()||!offer.scope?.trim())throw Error('Enter a positive price, availability and scope.');const previous=r.offers.findIndex(x=>x.providerId===offer.providerId);const item={...offer,price:Number(offer.price),id:previous<0?'o'+Date.now():r.offers[previous].id};if(previous<0)r.offers.push(item);else r.offers[previous]=item;r.events.push(previous<0?'New provider offer received':'Provider revised an offer');return item;}
function acceptOffer(r,id,role){if(role!=='customer')throw Error('Only the customer can select a provider.');if(r.status!=='Open')throw Error('A provider has already been selected or the request is closed.');const o=r.offers.find(x=>x.id===id);if(!o)throw Error('Offer not found.');r.accepted=JSON.parse(JSON.stringify(o));r.status='Assigned';r.events.push('Customer selected a provider and recorded the agreement');}
function transition(r,action,role){
 if(action==='cancel'){if(r.status==='Open'&&role==='customer'){r.status='Cancelled';r.events.push('Customer cancelled the open request');return;}if(['Assigned','In progress','Awaiting confirmation'].includes(r.status)&&!r.cancelBy){r.cancelBy=role;r.events.push(role+' requested cancellation');return;}throw Error('Cancellation is not available.');}
 if(action==='confirm-cancel'){if(!r.cancelBy||r.cancelBy===role)throw Error('The other party must confirm cancellation.');r.status='Cancelled';r.cancelBy=null;r.events.push('Both parties confirmed cancellation');return;}
 if(r.cancelBy)throw Error('Resolve the cancellation request first.');
 const rules={start:['Assigned','provider','In progress'],ready:['In progress','provider','Awaiting confirmation'],complete:['Awaiting confirmation','customer','Completed'],corrections:['Awaiting confirmation','customer','In progress']};const x=rules[action];if(!x||r.status!==x[0]||role!==x[1])throw Error('This action is not available in the current role or state.');r.status=x[2];r.events.push('Job moved to '+r.status);
}
function addReview(r,rating,comment,role){if(role!=='customer'||r.status!=='Completed'||r.review)throw Error('Only one customer review is allowed after completion.');if(!Number.isInteger(Number(rating))||rating<1||rating>5)throw Error('Choose a rating from 1 to 5.');r.review={rating:Number(rating),comment:comment.trim()};r.events.push('Customer submitted a completed-job review');}

const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>x==null?'Flexible':new Intl.NumberFormat('en-US').format(x)+' KZT';
let state;try{state=JSON.parse(localStorage.getItem('uycare-demo-v1'))}catch{}if(!state?.requests||state.version!==1)state=seed();
let nav='requests',sort='recommended',filter='All categories';
const current=()=>state.requests.find(x=>x.id===state.selected)||state.requests[0];
function save(){try{localStorage.setItem('uycare-demo-v1',JSON.stringify(state))}catch{}render()}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function modal(html){$('#modal-body').innerHTML=html;$('#modal').showModal()}
function close(){$('#modal').close()}
function error(form,e){form.querySelector('.error').textContent=e.message}
function profile(id){const p=profiles.find(x=>x.id===id);modal(`<div class="profile-heading"><span class="avatar">${p.initials}</span><div><h2>${p.name}</h2><span class="subdued">${p.trade}</span></div></div><span class="badge">Fictional demo profile</span><p class="rating">${p.count?'★ '+p.rating+' <span>'+p.count+' demo reviews</span>':'No reviews yet'}</p><p>${p.bio}</p><p class="subdued">${p.experience}<br>Almaty · Identity has not been verified</p><h3>Portfolio</h3><div class="portfolio">${p.works.map(w=>`<div><div class="work-image" aria-label="Illustrative portfolio placeholder">⌂</div><p>${w}</p><small>Illustration placeholder, not a real job photo</small></div>`).join('')}</div><h3>Customer feedback</h3>${p.reviews.length?p.reviews.map(t=>`<div class="review">“${t}”<div class="hint">Fictional review for this prototype</div></div>`).join(''):'<p class="subdued">This provider has no completed-job reviews yet.</p>'}`)}
function offerCard(o,r,selected=false){const p=profiles.find(x=>x.id===o.providerId);return `<article class="offer"><div class="offer-top"><span class="avatar">${p.initials}</span><div class="offer-person"><h3>${p.name}</h3><small>${p.trade}</small></div><div class="price">${money(o.price)}<small>proposed total</small></div></div><div class="rating">${p.count?'★ '+p.rating+' <span>('+p.count+' demo reviews)</span>':'No reviews yet <span>New to UyCare</span>'}</div><p>${esc(o.scope)}</p><div class="offer-bottom"><span class="availability">◷ ${esc(o.time)}</span><div class="offer-actions"><button class="secondary" data-profile="${p.id}">View profile</button>${selected?'<span class="badge">Selected</span>':state.role==='customer'&&r.status==='Open'?`<button class="primary" data-select="${o.id}">Choose specialist</button>`:''}</div></div></article>`}
function panel(r){return `<section class="request-panel"><span class="badge ${r.status==='Cancelled'?'warn':''}">${esc(r.status)}</span><h2>${esc(r.title)}</h2><p class="subdued">${esc(r.description)}</p><div class="details"><div class="detail-row"><span>Category</span><span>${esc(r.category)}</span></div><div class="detail-row"><span>Property</span><span>${esc(r.property)}</span></div><div class="detail-row"><span>Location</span><span>${esc(r.area)}</span></div><div class="detail-row"><span>Preferred date</span><span>${esc(r.date)}</span></div></div><div class="budget"><small>YOUR INDICATIVE BUDGET</small><b>${money(r.budget)}</b><em>Final scope and price come from the accepted offer.</em></div><p class="privacy">Exact address and phone contact are not public. Payment is arranged directly with the specialist.</p>${state.role==='customer'&&r.status==='Open'?'<button class="text-button danger" data-action="cancel">Cancel request</button>':''}<div class="little-label" style="margin-top:24px">ACTIVITY</div><ol class="timeline">${r.events.map(e=>'<li>'+esc(e)+'</li>').join('')}</ol></section>`}
function chat(r){return `<section class="chat"><h3>Job conversation</h3><p class="note">Local demonstration. Messages stay in this browser and are not sent to a real specialist.</p><div class="messages">${r.messages.length?r.messages.map(m=>`<div class="message"><small>${esc(m.role)} · local demo</small>${esc(m.text)}</div>`).join(''):'<p class="subdued">Clarify the scope, arrival time or materials here.</p>'}</div><form id="chat-form"><input name="message" aria-label="Message" placeholder="Write a message…" required maxlength="1000"><button class="primary">Send</button></form></section>`}
function job(r){let controls='';if(r.cancelBy){controls=`<p class="note">${esc(r.cancelBy)} requested cancellation.</p>${r.cancelBy!==state.role?'<button class="secondary" data-action="confirm-cancel">Confirm cancellation</button>':'<p class="note">Switch to the other demo role to confirm.</p>'}`;}else{if(r.status==='Assigned'&&state.role==='provider')controls='<button class="primary" data-action="start">Start work</button>';if(r.status==='In progress'&&state.role==='provider')controls='<button class="primary" data-action="ready">Mark ready for confirmation</button>';if(r.status==='Awaiting confirmation'&&state.role==='customer')controls='<button class="primary" data-action="complete">Confirm completion</button> <button class="secondary" data-action="corrections">Request corrections</button>';if(['Assigned','In progress','Awaiting confirmation'].includes(r.status))controls+=' <button class="text-button danger" data-action="cancel">Request cancellation</button>';}
return `${r.accepted?offerCard(r.accepted,r,true):''}<div class="job-status"><b>${esc(r.status)}</b><p>${r.status==='Assigned'?'The provider can start work from Provider view.':r.status==='In progress'?'The provider will mark the work ready for your confirmation.':r.status==='Awaiting confirmation'?'The customer can confirm completion or request corrections.':r.status==='Completed'?'The completed agreement remains available in your history.':'This request is closed.'}</p></div>${controls}${r.status==='Completed'?r.review?`<div class="chat"><h3>Your review</h3><p>★ ${r.review.rating} / 5</p><p>${esc(r.review.comment)}</p></div>`:state.role==='customer'?'<div class="chat"><h3>Review the completed work</h3><form id="review-form"><label class="field">Rating<select name="rating"><option value="5">5 — Excellent</option><option value="4">4 — Good</option><option value="3">3 — Fair</option><option value="2">2 — Poor</option><option value="1">1 — Very poor</option></select></label><label class="field">Comment<textarea name="comment" placeholder="Describe your experience"></textarea></label><div class="error"></div><button class="primary">Submit review</button></form></div>':'':''}${r.accepted?chat(r):''}`}
function render(){
$('#role').value=state.role;$('#role-label').textContent=state.role==='customer'?'Customer view':'Provider view';$('#new').hidden=state.role==='provider';document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.nav===nav));$('#page-title').textContent=nav==='messages'?'Job conversations':nav==='guide'?'How UyCare works':state.role==='provider'?'Find your next job':'My repair requests';
if(nav==='guide'){$('#app').innerHTML=`<section class="request-panel"><h2>A clear path from request to repair</h2>${[['01 / Describe the work','Publish a request with the category, area, timing and indicative budget.'],['02 / Compare proposals','Providers suggest prices and availability. Check what each quote includes.'],['03 / Choose a specialist','You decide who is right for the job. The accepted offer becomes your recorded agreement.'],['04 / Coordinate and confirm','Discuss details, follow progress and confirm completion before reviewing.']].map(([a,b])=>`<div class="guide-step"><b>${a}</b><p>${b}</p></div>`).join('')}<p class="note" style="margin-top:20px">Prototype limits: fictional data, browser-local state, rule-based category demonstration. No real login, trained ML, payment or mobile app is connected.</p></section>`;return;}
const r=current();if(nav==='messages'){$('#app').innerHTML=r?.accepted?chat(r):'<div class="empty"><h2>No job conversation yet</h2><p>Choose a specialist on a request to open the demonstration chat.</p></div>';bind();return;}
const visible=state.requests.filter(x=>state.role==='customer'||filter==='All categories'||x.category===filter);
$('#app').innerHTML=`<div class="overview"><div class="stat"><strong>${state.requests.filter(x=>x.status==='Open').length}</strong> Open requests</div><div class="stat"><strong>${state.requests.reduce((a,x)=>a+x.offers.length,0)}</strong> Offers received</div><div class="stat"><strong>${state.requests.filter(x=>x.status==='Completed').length}</strong> Completed</div></div>${state.role==='provider'?`<div class="filter-row"><span class="subdued">Browse by category</span><select id="category-filter">${['All categories',...categories].map(c=>`<option ${c===filter?'selected':''}>${c}</option>`).join('')}</select><span class="note">You are responding as the fictional provider Ayan M.</span></div>`:''}<div class="request-strip">${visible.map(x=>`<button class="request-tab ${x.id===r?.id?'active':''}" data-request="${x.id}"><b>${esc(x.title)}</b>${esc(x.status)} · ${x.offers.length} offers</button>`).join('')}</div>${!visible.length?'<div class="empty"><h2>No matching requests</h2><p>Try another category.</p></div>':r?`<div class="detail-grid">${panel(r)}<section>${r.status==='Open'?state.role==='customer'?`<div class="section-head"><h2>Offers for your request <span class="subdued">(${r.offers.length})</span></h2><select id="sort" aria-label="Sort offers"><option value="recommended" ${sort==='recommended'?'selected':''}>Received order</option><option value="price" ${sort==='price'?'selected':''}>Price: low to high</option><option value="rating" ${sort==='rating'?'selected':''}>Highest rating</option></select></div>${r.offers.length?[...r.offers].sort((a,b)=>sort==='price'?a.price-b.price:sort==='rating'?profiles.find(p=>p.id===b.providerId).rating-profiles.find(p=>p.id===a.providerId).rating:0).map(o=>offerCard(o,r)).join(''):'<div class="empty"><h3>Your request is open</h3><p>Switch to Provider view to send the first demo offer.</p></div>'}<p class="note">You choose the specialist. Compare the scope and availability as well as the price. All profiles shown here are fictional.</p>`:`<section class="offer"><h2>Send your offer</h2><p class="subdued">Specify the scope so the customer can compare proposals.</p><form id="offer-form"><label class="field">Proposed price in KZT<input name="price" type="number" min="1" step="1" required placeholder="15000"></label><label class="field">Availability<input name="time" required placeholder="25 October, 10:00–12:00"></label><label class="field">Included work and materials<textarea name="scope" required placeholder="Labour and travel included. Materials agreed separately."></textarea></label><div class="error"></div><button class="primary">Send offer</button></form></section><p class="note">Submitting again revises this demo provider's existing offer.</p>`:job(r)}</section></div>`:''}`;bind();}
function bind(){document.querySelectorAll('[data-request]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.request;save()});document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>profile(b.dataset.profile));document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{const r=current(),o=r.offers.find(x=>x.id===b.dataset.select),p=profiles.find(x=>x.id===o.providerId);modal(`<h2>Choose ${p.name}?</h2><p>This records the offer as your agreement.</p><div class="budget"><small>AGREED PRICE</small><b>${money(o.price)}</b></div><p>${esc(o.scope)}</p><p class="subdued">${esc(o.time)}<br>Payment is arranged directly. No money will be charged.</p><div class="form-actions"><button class="secondary" id="back">Go back</button><button class="primary" id="confirm">Confirm selection</button></div>`);$('#back').onclick=close;$('#confirm').onclick=()=>{try{acceptOffer(r,o.id,state.role);close();save();toast('Specialist selected. Agreement recorded locally.')}catch(e){toast(e.message)}}});
document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{try{transition(current(),b.dataset.action,state.role);save();toast('Demo status updated.')}catch(e){toast(e.message)}});
if($('#sort'))$('#sort').onchange=e=>{sort=e.target.value;render()};if($('#category-filter'))$('#category-filter').onchange=e=>{filter=e.target.value;const first=state.requests.find(x=>filter==='All categories'||x.category===filter);if(first)state.selected=first.id;render()};
if($('#offer-form'))$('#offer-form').onsubmit=e=>{e.preventDefault();try{submitOffer(current(),{...Object.fromEntries(new FormData(e.target)),providerId:'p1'});save();toast('Offer saved. Switch to Customer view to compare.')}catch(x){error(e.target,x)}};
if($('#chat-form'))$('#chat-form').onsubmit=e=>{e.preventDefault();const text=new FormData(e.target).get('message').trim();if(text){current().messages.push({role:state.role,text});save();toast('Message saved locally.')}};
if($('#review-form'))$('#review-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{addReview(current(),d.rating,d.comment,state.role);save();toast('Review saved for this completed demo job.')}catch(x){error(e.target,x)}};}
$('#new').onclick=()=>{modal(`<span class="eyebrow">NEW REPAIR REQUEST</span><h2>What needs fixing?</h2><p class="subdued">Give specialists enough detail to propose a useful offer.</p><form id="request-form"><label class="field">Request title<input name="title" required maxlength="100" placeholder="e.g. Fix a leaking kitchen sink"></label><label class="field">Describe the work<textarea name="description" id="description" required maxlength="2000" placeholder="What is the problem? What should the specialist know?"></textarea></label><div class="suggestion" id="suggestion">Category assistant: write a description to see a rule-based demo suggestion.</div><div class="form-grid"><label class="field">Category<select name="category" id="category"><option value="">Choose a category</option>${categories.map(c=>`<option>${c}</option>`).join('')}</select></label><label class="field">Property<select name="property"><option>Apartment</option><option>Private home</option><option>OSI/KSK shared area</option></select></label><label class="field">City and district<input name="area" required placeholder="Almaty, Bostandyk district"></label><label class="field">Preferred date<input name="date" type="date" required></label><label class="field">Indicative budget in KZT<input name="budget" type="number" min="1" step="1" placeholder="Optional"></label></div><p class="privacy">Use approximate location only in this demo. Photo uploads and organisation membership verification are specified for the production application.</p><div class="error"></div><div class="form-actions"><button type="button" class="secondary" id="cancel-form">Cancel</button><button class="primary">Publish request</button></div></form>`);$('#cancel-form').onclick=close;$('#description').oninput=e=>{const c=suggestCategory(e.target.value);$('#suggestion').innerHTML=c?`Rule-based demo suggestion: <b>${c}</b> <button type="button" class="text-button" id="use-category">Use category</button><span class="hint">You can choose a different category. This is not a trained ML result.</span>`:'No clear category suggestion. Please select a category manually.';if($('#use-category'))$('#use-category').onclick=()=>{$('#category').value=c}};$('#request-form').onsubmit=e=>{e.preventDefault();try{createRequest(state,Object.fromEntries(new FormData(e.target)));nav='requests';close();save();toast('Your demo request is open for offers.')}catch(x){error(e.target,x)}}};
$('#role').onchange=e=>{state.role=e.target.value;nav=state.role==='provider'?'work':'requests';save()};document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{nav=b.dataset.nav;if(nav==='work')state.role='provider';if(nav==='requests')state.role='customer';save()});$('.close').onclick=close;$('#reset').onclick=()=>{modal('<h2>Reset the demo?</h2><p>This removes only the fictional requests and messages saved by this prototype in this browser.</p><div class="form-actions"><button class="secondary" id="keep">Keep my demo</button><button class="primary" id="reset-confirm">Reset demo</button></div>');$('#keep').onclick=close;$('#reset-confirm').onclick=()=>{state=seed();nav='requests';sort='recommended';filter='All categories';close();save();toast('Sample data restored.')}};render();

})();
